        out = [row[:] for row in grid]
        for r in range(2):
            for c in range(2):
                if out[r][c] == 0:
                    out[r][c] = out[1-r][1-c]
        return out

    # Infer the direction of the parallel stripes, favoring constant c-r.
    # Group clues by diagonal and retain the clue color for each diagonal.
    groups = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                d = c-r
                groups.setdefault(d, []).append(grid[r][c])
    diag_color = {d: vals[0] for d, vals in groups.items()}

    # Pattern period is the smallest spacing that aligns the same clue color
    # on repeated diagonals; if the clues are sparse, infer it by periodic
    # assignments over the observed diagonal offsets.
    period = None
    for p in range(1, max(h, w)+1):
