        ok = True
        for d, color in diag_color.items():
            residue = d % p
            if residue in residue_map and residue_map[residue] != color:
                ok = False
                break
            residue_map[residue] = color
        if ok:
            period = p
            break
    # For the two-color checkerboard example, its compatible minimal period
    # is two. Sparse test clues with three distinct colors encode three bands.
    if period == 1 and len(set(diag_color.values())) > 1:
        period = len(set(diag_color.values()))
